//! Settings, Open source licences: Voxa's NOTICE, then every library, font and model this build
//! ships, with its licence text. The data is generated by tools/licences/generate.py from the real
//! dependency graph (docs/guardrails.md#11-licences) and embedded gzipped; flate2 is already in
//! GPUI's tree.

use std::io::Read;
use std::sync::OnceLock;

use serde::Deserialize;

#[cfg(target_os = "macos")]
static GZ: &[u8] = include_bytes!("../assets/licences-macos.json.gz");
#[cfg(not(target_os = "macos"))]
static GZ: &[u8] = include_bytes!("../assets/licences-windows.json.gz");

#[derive(Deserialize)]
pub struct Notices {
    #[cfg_attr(not(test), allow(dead_code))]
    pub app: String,
    /// Voxa's own NOTICE, verbatim.
    pub notice: String,
    pub libraries: Vec<Library>,
    pub texts: Vec<String>,
}

#[derive(Deserialize)]
pub struct Library {
    pub name: String,
    pub version: String,
    pub kind: String,
    /// SPDX expression, e.g. "MIT OR Apache-2.0".
    pub licence: String,
    #[serde(default)]
    pub source: String,
    #[serde(default)]
    pub note: String,
    /// Indexes into `Notices::texts`.
    pub texts: Vec<usize>,
}

fn decode(gz: &[u8]) -> Result<Notices, String> {
    let mut json = String::new();
    flate2::read::GzDecoder::new(gz).read_to_string(&mut json).map_err(|e| format!("licences: {e}"))?;
    serde_json::from_str(&json).map_err(|e| format!("licences: {e}"))
}

/// Decompressed on first use (about a megabyte of text), then kept.
pub fn get() -> Option<&'static Notices> {
    static N: OnceLock<Option<Notices>> = OnceLock::new();
    N.get_or_init(|| decode(GZ).map_err(|e| crate::common::log(&e)).ok()).as_ref()
}

/// What the page says about one library: "MIT OR Apache-2.0" reads "MIT or Apache 2.0".
pub fn plain_licence(spdx: &str) -> String {
    spdx.replace(" OR ", " or ").replace(" AND ", " and ").replace(" WITH ", " with ").replace('/', " or ").replace("  ", " ")
}

/// A text longer than this shows its first lines, with a button for the whole text.
pub const PREVIEW_LINES: usize = 120;

pub fn preview(text: &str) -> (String, bool) {
    let mut lines = text.lines();
    let head: Vec<&str> = lines.by_ref().take(PREVIEW_LINES).collect();
    let more = lines.next().is_some();
    (head.join("\n"), more)
}

/// The whole text in a file under the data folder, opened in the default text editor (only when
/// the person asks: a click on "Open full text").
pub fn open_full(name: &str, text: &str) {
    let dir = crate::data_dir().join("licences");
    let safe: String = name.chars().map(|c| if c.is_ascii_alphanumeric() || c == '-' || c == '_' { c } else { '_' }).collect();
    let path = dir.join(format!("{safe}.txt"));
    let ok = std::fs::create_dir_all(&dir).is_ok() && crate::store::write_atomic(&path, text.as_bytes()).is_ok();
    if ok {
        crate::os::open(path.as_os_str());
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Apache-2.0 section 4(d): the licences page carries Voxa's NOTICE, first, crediting the author.
    #[test]
    fn the_embedded_licences_decompress_and_start_with_voxas_notice() {
        let n = decode(GZ).expect("the embedded licences decompress and parse");
        assert!(n.notice.starts_with("Voxa\n"), "the NOTICE comes first: {:?}", &n.notice[..40.min(n.notice.len())]);
        assert!(n.notice.contains("created by Simiyon Vinscent Samuel L"));
        assert!(n.notice.contains("Apache License, Version 2.0"));
        let ours = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/../../NOTICE")).unwrap().replace("\r\n", "\n");
        assert_eq!(n.notice.trim(), ours.trim(), "the embedded NOTICE is today's NOTICE (regenerate with tools/licences/generate.py)");
        #[cfg(target_os = "macos")]
        assert_eq!(n.app, "macos");
        #[cfg(not(target_os = "macos"))]
        assert_eq!(n.app, "windows");
    }

    #[test]
    fn every_library_has_a_licence_and_its_texts_exist() {
        let n = decode(GZ).unwrap();
        assert!(n.libraries.len() > 100, "the desktop links hundreds of crates");
        for want in ["gpui", "serde", "Rust standard library", "ONNX Runtime", "Fraunces font"] {
            assert!(n.libraries.iter().any(|l| l.name == want), "{want} is listed");
        }
        for l in &n.libraries {
            assert!(!l.licence.is_empty(), "{} has a licence", l.name);
            assert!(!l.texts.is_empty(), "{} has a licence text", l.name);
            assert!(l.texts.iter().all(|&t| t < n.texts.len()), "{} points at real texts", l.name);
        }
    }

    #[test]
    fn licences_read_as_plain_words_and_long_texts_are_previewed() {
        assert_eq!(plain_licence("MIT OR Apache-2.0"), "MIT or Apache-2.0");
        assert_eq!(plain_licence("MIT/Apache-2.0"), "MIT or Apache-2.0");
        let long = (0..500).map(|i| i.to_string()).collect::<Vec<_>>().join("\n");
        let (head, more) = preview(&long);
        assert!(more);
        assert_eq!(head.lines().count(), PREVIEW_LINES);
        assert_eq!(preview("short\ntext"), ("short\ntext".to_string(), false));
    }
}
